import{Kc as a}from"./chunk-XXQ56O26.js";var s={checkedAt:"2026-10-16",household:"One adult, no children, living in Austin",benchmarks:[{topic:"Housing",published:"HUD FY 2027: $1,530 gross rent for one bedroom; $1,817 for two.",use:"The baseline one-bedroom picture totals $1,530 including its utility allowance. Other home levels are planning choices.",url:"https://www.huduser.gov/portal/datasets/fmr/fmr2027/FY2027_FMR_Schedule.pdf"},{topic:"Buying a home",published:"Austin metro median closed sale: $421,000, September 2026. Freddie Mac 30-year rate: 7.40%, October 15.",use:"Price and rate anchors are sourced. Taxes, insurance, HOA, maintenance, closing costs, and PMI are editable assumptions. A median sale is not a promise of a particular house.",url:"https://www.unlockmls.com/news/september-2026-central-texas-housing-report",extraURL:"https://www.freddiemac.com/pmms"},{topic:"Groceries and health",published:"MIT Travis County 2026 basic-needs reference: food about $347/month and medical about $256/month.",use:"Frugal groceries now use $350, with higher choices for variety and convenience. The health allowance is an assumption. A basic-needs budget is not a leisure-and-savings lifestyle.",url:"https://livingwage.mit.edu/counties/48453"},{topic:"Driving",published:"Experian Q2 2026 national loan averages: used 11.19%; new 6.35%.",use:"New picture choices use these APRs. Car prices, insurance, fuel, parking, and maintenance remain scenarios. A paid-off car includes an allowance for replacement. Down payments are separate from monthly spending.",url:"https://www.experian.com/blogs/ask-experian/average-car-payment/"},{topic:"Transit",published:"CapMetro local calendar-month fare: $41.25. Rail/Express commuter fare: $96.25. Fare change announced for January 10, 2027.",use:"The lowest-cost transit choice uses local service, plus an assumed rides budget. It does not include unlimited commuter rail or guarantee a workable route.",url:"https://www.capmetro.org/fare/general-fares-overview/fares"},{topic:"Low-down-payment mortgages",published:"Freddie Mac\u2019s broad PMI guide is $30\u2013$70/month per $100,000 borrowed.",use:"Below 20% down, the model now adds PMI. Default 0.6% annually equals $50/month per $100,000. This is a midpoint estimate, not an insurance quote.",url:"https://myhome.freddiemac.com/buying/breaking-down-pmi"},{topic:"Restaurants, travel, hobbies, and clothes",published:"No source establishes a universal salary-to-brand, holiday, or restaurant lifestyle.",use:"These are chosen spending baskets, not measured Austin price bands. Dinner amounts include assumed tax and tip. Weekly dinners convert at 52/12 weeks per month.",url:"https://www.bls.gov/cex/csxgloss.htm"}]};function r(){return`<a class="text-link" href="./developer.html#finance">\u2190 Developer \xB7 financial review</a><div class="page-intro guide-intro"><span class="eyebrow">CHECKED OCTOBER 17, 2026</span><h1>What\u2019s sourced. What\u2019s estimated.</h1><p>Clear labels for a useful planning picture.</p></div><div class="review-cards"><section class="guide-input-panel"><h2>Starting pay: official wage proxy</h2><p>TWC uses the average of the lowest-paid third. It does not observe first-job pay. Austin is used where available; psychiatric aides use Dallas.</p><p>Later milestones use 112 recovered experienced-wage benchmarks where available, with explicit modeled fractions between entry and mature pay. They are not measured year-by-year salaries. AISD and Austin Police provide employer schedules. Austin Fire, Dell residency and ETA apprenticeship have separate published training or qualified-pay examples. Tattoo pay uses a small posting sample.</p><a href="https://texaswages.com/Home/About" target="_blank" rel="noopener noreferrer">TWC definitions \u2197</a></section><section class="guide-input-panel"><h2>Education: published examples</h2><p>Undergraduate costs and later professional study appear separately. Each amount names its year and what it includes. Older, undated, and derived figures carry those labels.</p><a href="https://onestop.utexas.edu/managing-costs/cost-tuition-rates/cost-of-attendance/" target="_blank" rel="noopener noreferrer">UT Austin budget \u2197</a></section><section class="guide-input-panel"><h2>Lifestyle: a conditional budget</h2><p>Home and transit benchmarks are sourced. Most spending choices are editable estimates. A budget that fits a salary does not predict that you will earn it.</p><p>Income ranges show coverage and breathing room. They are not probabilities. Student borrowing starts at zero. The education budget can link the selected loan payment to lifestyle expenses. Paid-hours and independent-work scenarios use separate assumptions and tax calculations.</p></section></div><h2>Austin cost checks</h2>${s.benchmarks.map(e=>`<details class="more-info"><summary>${a(e.topic)}</summary><div><p><strong>${a(e.published)}</strong></p><p>${a(e.use)}</p><a href="${a(e.url)}" target="_blank" rel="noopener noreferrer">Established source \u2197</a>${e.extraURL?` \xB7 <a href="${e.extraURL}" target="_blank" rel="noopener noreferrer">Rate source \u2197</a>`:""}</div></details>`).join("")}<details class="more-info"><summary>What this review does not validate</summary><p>The career connections organize exploration. They are not validated predictions of aptitude, admission, satisfaction, or future earnings. Official O*NET scores stay separate from personal reflections, confidence, income goals, and budget choices. Software checks confirm rules and arithmetic; they do not establish these real-world outcomes.</p></details>`}export{s as financialReview,r as sourceReviewPage};
